"""Nightly billing summary for hotel front-desk exports."""

from __future__ import annotations

import datetime
import json
from dataclasses import dataclass

RATE_MULTIPLIERS = {
    "standard": 1.0,
    "member": 0.9,
    "corporate": 0.85,
    "promo": 0.75,
}

LATE_CHECKOUT_FEE = 25.0


@dataclass
class Reservation:
    guest_name: str
    room_number: str
    check_in: str
    check_out: str
    rate_plan: str = "standard"
    late_checkout: bool = False


def load_reservations(path: str) -> list[Reservation]:
    with open(path) as f:
        raw = json.load(f)
    return [Reservation(**r) for r in raw]


def _nights_between(check_in: str, check_out: str) -> int:
    fmt = "%Y-%m-%d"
    start = datetime.datetime.strptime(check_in, fmt)
    end = datetime.datetime.strptime(check_out, fmt)
    return (end - start).days


def _rate_multiplier(rate_plan: str) -> float:
    try:
        return RATE_MULTIPLIERS[rate_plan]
    except KeyError:
        return RATE_MULTIPLIERS["standard"]


def _apply_rate_plan_and_validate(
    reservation: Reservation, nights: int, base_rate: float
) -> float:
    if nights <= 0:
        raise ValueError(
            f"reservation for room {reservation.room_number} has a non-positive "
            "stay length"
        )
    subtotal = nights * base_rate * _rate_multiplier(reservation.rate_plan)
    if reservation.late_checkout:
        subtotal += LATE_CHECKOUT_FEE
    return round(subtotal, 2)


def compute_charge(reservation: Reservation, base_rate: float) -> float:
    nights = _nights_between(reservation.check_in, reservation.check_out)
    return _apply_rate_plan_and_validate(reservation, nights, base_rate)


def generate_billing_summary(path: str, base_rate: float) -> dict[str, float]:
    """Return a mapping of room number to total charge for the stay."""
    reservations = load_reservations(path)
    totals: dict[str, float] = {}
    for reservation in reservations:
        amount = compute_charge(reservation, base_rate)
        totals[reservation.room_number] = amount
    return totals
